CREATE TABLE client_progress_statement_variations(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,statement_id BIGINT UNSIGNED NOT NULL,contract_variation_id BIGINT UNSIGNED NOT NULL,variation_code_snapshot VARCHAR(30) NULL,variation_number_snapshot VARCHAR(50) NULL,variation_title_snapshot VARCHAR(190) NULL,amount_effect_snapshot VARCHAR(20) NULL,approved_variation_amount_snapshot DECIMAL(18,2) NULL,previous_billed_amount DECIMAL(18,2) NULL,current_billed_amount DECIMAL(18,2) NOT NULL,cumulative_billed_amount DECIMAL(18,2) NULL,signed_current_amount DECIMAL(18,2) NULL,is_committed TINYINT(1) NOT NULL DEFAULT 0,sort_order INT UNSIGNED NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_cps_variation_statement(statement_id,contract_variation_id),KEY idx_cps_variation_source(contract_variation_id,is_committed),CONSTRAINT fk_cps_variation_statement FOREIGN KEY(statement_id) REFERENCES client_progress_statements(id) ON DELETE RESTRICT,CONSTRAINT fk_cps_variation_source FOREIGN KEY(contract_variation_id) REFERENCES contract_variations(id) ON DELETE RESTRICT,CONSTRAINT chk_cps_variation_current CHECK(current_billed_amount>0),CONSTRAINT chk_cps_variation_committed CHECK(is_committed IN(0,1)),CONSTRAINT chk_cps_variation_effect CHECK(amount_effect_snapshot IS NULL OR amount_effect_snapshot IN('increase','decrease')),CONSTRAINT chk_cps_variation_snapshots CHECK((is_committed=0 AND variation_code_snapshot IS NULL AND variation_number_snapshot IS NULL AND variation_title_snapshot IS NULL AND amount_effect_snapshot IS NULL AND approved_variation_amount_snapshot IS NULL AND previous_billed_amount IS NULL AND cumulative_billed_amount IS NULL AND signed_current_amount IS NULL) OR(is_committed=1 AND variation_code_snapshot IS NOT NULL AND variation_title_snapshot IS NOT NULL AND amount_effect_snapshot IS NOT NULL AND approved_variation_amount_snapshot>=0 AND previous_billed_amount>=0 AND cumulative_billed_amount>=current_billed_amount AND signed_current_amount IS NOT NULL))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
